function ProjectForm() {
  const navigate = useNavigate();
  const [aiPlan, setAiPlan] = useState(false);
  const [priority, setPriority] = useState("media");
  const [difficulty, setDifficulty] = useState("media");
  const fieldClass = "mt-2 w-full rounded-xl border border-[var(--ui-ink)]/25 bg-[var(--ui-surface)] px-3.5 py-3 text-sm outline-none transition placeholder:text-[var(--ui-muted)]/65 focus:border-[var(--ui-ink)] focus:ring-2 focus:ring-[var(--ui-accent)]";
  const labelClass = "font-mono text-[10px] font-semibold uppercase tracking-[0.11em] text-[var(--ui-muted)]";

  return <div className="mobile-scroll fixed inset-x-0 bottom-0 top-[78px] z-30 overflow-y-auto overscroll-contain bg-[var(--ui-action)]/20 p-3 backdrop-blur-sm sm:inset-0 sm:p-7" role="dialog" aria-modal="true" aria-labelledby="form-title">
    <div className="mx-auto min-h-full max-w-[900px] rounded-[28px] border border-[var(--ui-ink)]/25 bg-[var(--ui-surface)] shadow-[0_22px_70px_rgba(32,33,31,0.22)]">
      <div className="flex items-center justify-between border-b border-[var(--ui-ink)]/15 bg-[var(--ui-panel)] px-5 py-4 sm:px-8">
        <div><p className="font-mono text-[10px] font-semibold uppercase tracking-[0.13em] text-[var(--ui-muted)]">Nuevo espacio de trabajo</p><h2 id="form-title" className="mt-1 font-[family-name:var(--font-display)] text-2xl tracking-[-0.035em]">Añadir proyecto</h2></div>
        <button onClick={() => navigate("/")} className="group grid h-10 w-10 place-items-center rounded-full border border-[var(--ui-ink)]/25 transition hover:bg-[var(--ui-surface)] focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-[var(--ui-ink)]" aria-label="Cerrar formulario"><span className="transition-transform duration-300 group-hover:rotate-90"><Icon name="close" /></span></button>
      </div>
      <form onSubmit={(event) => { event.preventDefault(); navigate("/"); }} className="p-5 sm:p-8">
        <div className="grid gap-6 md:grid-cols-2">
          <label className={`md:col-span-2 ${labelClass}`}>Nombre del proyecto<input required className={fieldClass} placeholder="Ej. Diseño de investigación" /></label>
          <label className={`md:col-span-2 ${labelClass}`}>Descripción<textarea className={`${fieldClass} min-h-24 resize-y`} placeholder="¿Qué quieres conseguir con este proyecto?" /></label>
          <label className={labelClass}>Fecha de inicio<input required type="date" className={fieldClass} /></label>
          <label className={labelClass}>Fecha límite<input required type="date" className={fieldClass} /></label>
          <fieldset className={labelClass}><legend>Prioridad</legend><div className="mt-2 grid grid-cols-3 gap-2">{[{ value: "baja", label: "Baja", color: "border-[var(--ui-success)] bg-[var(--ui-success-soft)] text-[var(--ui-success-ink)]" }, { value: "media", label: "Media", color: "border-[var(--ui-warning)] bg-[var(--ui-warning-soft)] text-[var(--ui-warning-ink)]" }, { value: "alta", label: "Alta", color: "border-[var(--ui-danger)] bg-[var(--ui-danger-soft)] text-[var(--ui-danger-ink)]" }].map((option) => <button key={option.value} type="button" onClick={() => setPriority(option.value)} aria-pressed={priority === option.value} className={`rounded-xl border px-2 py-3 text-[10px] font-semibold uppercase tracking-[0.05em] transition ${option.color} ${priority === option.value ? "ring-1 ring-[var(--ui-ink)] ring-offset-1" : ""}`}>{option.label}</button>)}</div></fieldset>
          <fieldset className={labelClass}><legend>Dificultad</legend><div className="mt-2 grid grid-cols-3 gap-2">{[{ value: "baja", label: "Baja", color: "border-[var(--ui-success)] bg-[var(--ui-success-soft)] text-[var(--ui-success-ink)]" }, { value: "media", label: "Media", color: "border-[var(--ui-warning)] bg-[var(--ui-warning-soft)] text-[var(--ui-warning-ink)]" }, { value: "alta", label: "Alta", color: "border-[var(--ui-danger)] bg-[var(--ui-danger-soft)] text-[var(--ui-danger-ink)]" }].map((option) => <button key={option.value} type="button" onClick={() => setDifficulty(option.value)} aria-pressed={difficulty === option.value} className={`rounded-xl border px-2 py-3 text-[10px] font-semibold uppercase tracking-[0.05em] transition ${option.color} ${difficulty === option.value ? "ring-1 ring-[var(--ui-ink)] ring-offset-1" : ""}`}>{option.label}</button>)}</div></fieldset>
          <label className={`md:col-span-2 ${labelClass}`}>Duración estimada<input className={fieldClass} placeholder="Ej. 18 horas · 3 semanas" /></label>
        </div>

        <section className="mt-8 rounded-2xl border border-[var(--ui-ink)]/20 bg-[var(--ui-panel)] p-5 sm:p-6" aria-labelledby="ai-title">
          <div className="flex flex-wrap items-start justify-between gap-4"><div className="flex gap-3"><span className="grid h-9 w-9 shrink-0 place-items-center rounded-full border border-[var(--ui-ink)]/25 bg-[var(--ui-surface)]"><Icon name="wand" size={18} /></span><div><h3 id="ai-title" className="font-[family-name:var(--font-display)] text-xl tracking-[-0.025em]">Planificar con asistente de IA</h3><p className="mt-1 max-w-[490px] text-sm leading-5 text-[var(--ui-muted)]">Crea una primera propuesta de tareas y subtareas según el objetivo, fecha y duración que indiques.</p></div></div><button type="button" onClick={() => setAiPlan(!aiPlan)} className="inline-flex items-center gap-2 rounded-full border border-[var(--ui-ink)] bg-[var(--ui-action)] px-4 py-2.5 font-mono text-[10px] font-semibold uppercase tracking-[0.08em] text-[var(--ui-surface)] transition hover:bg-[var(--ui-panel-hover)] focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-[var(--ui-ink)]"><Icon name={aiPlan ? "check" : "sparkle"} size={15} />{aiPlan ? "Propuesta lista" : "Dividir proyecto"}</button></div>
          {aiPlan && <div className="mt-5 grid gap-2 border-t border-[var(--ui-ink)]/15 pt-4 text-sm sm:grid-cols-3"><p className="rounded-lg border border-[var(--ui-ink)]/15 bg-[var(--ui-surface)]/75 p-3"><b className="block font-mono text-[9px] uppercase tracking-wider">01 · Preparar</b><span className="mt-1 block text-[var(--ui-muted)]">Definir alcance y fuentes.</span></p><p className="rounded-lg border border-[var(--ui-ink)]/15 bg-[var(--ui-surface)]/75 p-3"><b className="block font-mono text-[9px] uppercase tracking-wider">02 · Desarrollar</b><span className="mt-1 block text-[var(--ui-muted)]">Trabajar por entregables.</span></p><p className="rounded-lg border border-[var(--ui-ink)]/15 bg-[var(--ui-surface)]/75 p-3"><b className="block font-mono text-[9px] uppercase tracking-wider">03 · Revisar</b><span className="mt-1 block text-[var(--ui-muted)]">Editar y preparar entrega.</span></p></div>}
        </section>
        <div className="mt-8 flex flex-wrap justify-end gap-3 border-t border-[var(--ui-ink)]/15 pt-5"><button type="button" onClick={() => navigate("/")} className="rounded-full border border-[var(--ui-ink)]/25 px-5 py-3 font-mono text-[10px] font-semibold uppercase tracking-[0.09em] transition hover:bg-[var(--ui-panel-hover)]">Cancelar</button><button type="submit" className="rounded-full bg-[var(--ui-action)] px-5 py-3 font-mono text-[10px] font-semibold uppercase tracking-[0.09em] text-[var(--ui-surface)] transition hover:bg-[var(--ui-panel-hover)]">Crear proyecto</button></div>
      </form>
    </div>
  </div>;
}

