  return <div className="fixed inset-0 z-[70] grid place-items-end bg-[var(--ui-action)]/25 backdrop-blur-sm sm:place-items-center sm:p-6" role="dialog" aria-modal="true" aria-labelledby="delete-data-title"><section className="w-full max-w-[650px] overflow-hidden rounded-t-[30px] border border-[var(--ui-ink)]/25 bg-[var(--ui-surface)] shadow-[0_22px_70px_var(--ui-elevation)] sm:rounded-[30px]"><header className="flex items-center justify-between border-b border-[var(--ui-ink)]/15 bg-[var(--ui-panel)] px-6 py-5 sm:px-8"><div><p className="font-mono text-[10px] font-semibold uppercase tracking-[0.13em] text-[var(--ui-muted)]">Datos y privacidad · 02</p><h2 id="delete-data-title" className="mt-1 font-[family-name:var(--font-display)] text-3xl tracking-[-0.045em]">Eliminar datos</h2></div><button onClick={onClose} className="group grid h-10 w-10 place-items-center rounded-full border border-[var(--ui-ink)]/25 transition hover:bg-[var(--ui-surface)]" aria-label="Cerrar eliminación"><span className="transition-transform duration-300 group-hover:rotate-90"><Icon name="close" /></span></button></header><div className="px-6 py-7 sm:px-8 sm:py-8"><p className="text-sm leading-6 text-[var(--ui-muted)]">Selecciona los datos que quieres eliminar. Esta acción no se puede deshacer.</p><fieldset className="mt-6 space-y-3">{(["Notas", "Proyectos", "Todo"] as const).map((item) => <button key={item} type="button" onClick={() => setTarget(item)} aria-pressed={target === item} className={`flex w-full items-center justify-between rounded-2xl border p-4 text-left transition ${target === item ? "border-[var(--ui-danger)] bg-[var(--ui-danger-soft)]" : "border-[var(--ui-ink)]/20 hover:bg-[var(--ui-panel-hover)]"}`}><span><b className="block text-sm">{item === "Todo" ? "Todos los datos" : `Solo ${item.toLowerCase()}`}</b><span className="mt-1 block text-xs leading-5 text-[var(--ui-muted)]">{descriptions[item]}</span></span><span className={`grid h-5 w-5 place-items-center rounded-full border ${target === item ? "border-[var(--ui-danger)] bg-[var(--ui-danger)] text-[var(--ui-danger-soft)]" : "border-[var(--ui-ink)]/30"}`}>{target === item && "✓"}</span></button>)}</fieldset><div className="mt-6 rounded-2xl border border-[var(--ui-danger)]/45 bg-[var(--ui-danger-soft)] p-4 text-[var(--ui-danger-ink)]"><p className="text-sm font-semibold">Acción irreversible</p><p className="mt-1 text-xs leading-5">Una vez confirmada, no será posible recuperar los datos seleccionados.</p></div><div className="mt-7 flex flex-wrap justify-end gap-3 border-t border-[var(--ui-ink)]/15 pt-5"><button onClick={onClose} className="rounded-full border border-[var(--ui-ink)]/25 px-5 py-3 font-mono text-[10px] font-semibold uppercase tracking-[0.09em]">Cancelar</button><button onClick={() => setDeleted(true)} className="rounded-full bg-[var(--ui-danger)] px-5 py-3 font-mono text-[10px] font-semibold uppercase tracking-[0.09em] text-[var(--ui-danger-ink)] transition hover:brightness-95">Eliminar {target.toLowerCase()}</button></div></div></section></div>;
