function useMobileHeaderVisibility() {
  const [isHidden, setIsHidden] = useState(false);
  const lastScrollTop = useRef(0);
  const updateVisibility = (nextScrollTop: number) => {
    if (nextScrollTop < 12) setIsHidden(false);
    else if (nextScrollTop > lastScrollTop.current + 8) setIsHidden(true);
    else if (nextScrollTop < lastScrollTop.current - 8) setIsHidden(false);
    lastScrollTop.current = nextScrollTop;
  };
  const onScroll = (event: UIEvent<HTMLElement>) => {
    updateVisibility(event.currentTarget.scrollTop);
  };
  useEffect(() => {
    const onWindowScroll = () => { if (window.innerWidth >= 1024) updateVisibility(window.scrollY); };
    window.addEventListener("scroll", onWindowScroll, { passive: true });
    return () => window.removeEventListener("scroll", onWindowScroll);
  });
  return { isHidden, onScroll };
}

